CREATE TYPE public.service_line AS ENUM ('ORM','Marcom');
CREATE TYPE public.service_variant AS ENUM ('ORM','MT','GMB','ORM_LITE');
CREATE TYPE public.subscription_status AS ENUM ('ACTIVE','PAUSED','SUSPENDED','TERMINATED');
CREATE TYPE public.invoice_type AS ENUM ('SETUP','RECURRING','SYSTEM_FEE');
CREATE TYPE public.customer_segment AS ENUM ('NEW','EXISTING');
CREATE TYPE public.invoice_status AS ENUM ('ISSUED','PARTIALLY_PAID','PAID','OVERDUE','WRITTEN_OFF','VOID');
CREATE TYPE public.payment_grade AS ENUM ('A','B','C','D');
CREATE TYPE public.collection_event_type AS ENUM ('OVERDUE_FLAGGED','SUSPENDED','REACTIVATED','LEGAL_FILED','WRITTEN_OFF');
CREATE TYPE public.collection_status AS ENUM ('NORMAL','OVERDUE','SUSPENDED','LEGAL','WRITTEN_OFF');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,role text NOT NULL CHECK(role IN ('ac','legal','admin','billing_reader')),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.ac_has_role(roles text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=auth.uid() AND role=ANY(roles))$$;
REVOKE ALL ON FUNCTION public.ac_has_role(text[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.ac_has_role(text[]) TO authenticated;
CREATE TABLE public.hotel(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL);
GRANT SELECT ON public.hotel TO authenticated; GRANT ALL ON public.hotel TO service_role; ALTER TABLE public.hotel ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_read ON public.hotel FOR SELECT TO authenticated USING(public.ac_has_role(ARRAY['ac','legal','admin','billing_reader']));
CREATE TABLE public.customer(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL);
GRANT SELECT ON public.customer TO authenticated; GRANT ALL ON public.customer TO service_role; ALTER TABLE public.customer ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_read ON public.customer FOR SELECT TO authenticated USING(public.ac_has_role(ARRAY['ac','legal','admin','billing_reader']));
CREATE TABLE public.contract(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL);
GRANT SELECT ON public.contract TO authenticated; GRANT ALL ON public.contract TO service_role; ALTER TABLE public.contract ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_read ON public.contract FOR SELECT TO authenticated USING(public.ac_has_role(ARRAY['ac','legal','admin','billing_reader']));
CREATE TABLE public.member(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,user_id uuid UNIQUE);
GRANT SELECT ON public.member TO authenticated; GRANT ALL ON public.member TO service_role; ALTER TABLE public.member ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_read ON public.member FOR SELECT TO authenticated USING(public.ac_has_role(ARRAY['ac','legal','admin','billing_reader']));
CREATE TABLE public.service_subscription(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hotel_id uuid NOT NULL REFERENCES public.hotel,customer_id uuid NOT NULL REFERENCES public.customer,contract_id uuid NOT NULL REFERENCES public.contract,service_line public.service_line NOT NULL,service_variant public.service_variant,monthly_fee numeric(12,2) NOT NULL CHECK(monthly_fee>0),billing_day int NOT NULL DEFAULT 5 CHECK(billing_day BETWEEN 1 AND 28),due_day int NOT NULL DEFAULT 15 CHECK(due_day BETWEEN 1 AND 28 AND due_day>=billing_day),billing_start_date date NOT NULL,status public.subscription_status NOT NULL DEFAULT 'ACTIVE',orm_team_id uuid REFERENCES public.member,marcom_member_id uuid REFERENCES public.member,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(contract_id,service_line),CHECK(service_variant IS NULL OR (service_line='ORM' AND service_variant IN ('ORM','ORM_LITE')) OR (service_line='Marcom' AND service_variant IN ('MT','GMB'))));
GRANT SELECT ON public.service_subscription TO authenticated; GRANT ALL ON public.service_subscription TO service_role; ALTER TABLE public.service_subscription ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_read ON public.service_subscription FOR SELECT TO authenticated USING(public.ac_has_role(ARRAY['ac','legal','admin','billing_reader']));
CREATE TABLE public.invoice(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subscription_id uuid REFERENCES public.service_subscription,hotel_id uuid NOT NULL REFERENCES public.hotel,customer_id uuid NOT NULL REFERENCES public.customer,service_line public.service_line NOT NULL,invoice_type public.invoice_type NOT NULL,billing_period date CHECK(billing_period=date_trunc('month',billing_period)::date),customer_segment public.customer_segment NOT NULL,issue_date date NOT NULL,due_date date NOT NULL CHECK(due_date>=issue_date),amount numeric(12,2) NOT NULL CHECK(amount>0),paid_amount numeric(12,2) NOT NULL DEFAULT 0 CHECK(paid_amount>=0),settled_date date,gateway_paid_date date,tax_receipt_no text,status public.invoice_status NOT NULL DEFAULT 'ISSUED',cadence text CHECK(cadence IN ('monthly','quarterly')),created_at timestamptz NOT NULL DEFAULT now(),CHECK(invoice_type<>'RECURRING' OR (subscription_id IS NOT NULL AND billing_period IS NOT NULL)));
GRANT SELECT ON public.invoice TO authenticated; GRANT ALL ON public.invoice TO service_role; ALTER TABLE public.invoice ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_read ON public.invoice FOR SELECT TO authenticated USING(public.ac_has_role(ARRAY['ac','legal','admin','billing_reader']));
CREATE UNIQUE INDEX invoice_recurring_unique ON public.invoice(subscription_id,billing_period) WHERE invoice_type='RECURRING';
CREATE UNIQUE INDEX invoice_new_unique ON public.invoice(customer_id) WHERE customer_segment='NEW';
CREATE INDEX ON public.invoice(customer_id,billing_period); CREATE INDEX ON public.invoice(status); CREATE INDEX ON public.invoice(invoice_type,service_line);
CREATE TABLE public.payment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL REFERENCES public.invoice,gateway_paid_date date NOT NULL,amount numeric(12,2) NOT NULL CHECK(amount>0),method text NOT NULL,recorded_by uuid NOT NULL REFERENCES public.member,verified_by_ac boolean NOT NULL DEFAULT false,verified_at date,verified_by uuid REFERENCES public.member,created_at timestamptz NOT NULL DEFAULT now(),CHECK(verified_by_ac=(verified_at IS NOT NULL)));
GRANT SELECT ON public.payment TO authenticated; GRANT ALL ON public.payment TO service_role; ALTER TABLE public.payment ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_read ON public.payment FOR SELECT TO authenticated USING(public.ac_has_role(ARRAY['ac','legal','admin','billing_reader'])); CREATE INDEX ON public.payment(invoice_id);
CREATE TABLE public.payment_grade_record(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.customer,billing_period date NOT NULL,grade public.payment_grade NOT NULL,basis jsonb NOT NULL,computed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(customer_id,billing_period));
GRANT SELECT ON public.payment_grade_record TO authenticated; GRANT ALL ON public.payment_grade_record TO service_role; ALTER TABLE public.payment_grade_record ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_read ON public.payment_grade_record FOR SELECT TO authenticated USING(public.ac_has_role(ARRAY['ac','legal','admin','billing_reader']));
CREATE TABLE public.collection_event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hotel_id uuid NOT NULL REFERENCES public.hotel,customer_id uuid NOT NULL REFERENCES public.customer,subscription_id uuid REFERENCES public.service_subscription,event_type public.collection_event_type NOT NULL,occurred_at date NOT NULL DEFAULT (now() AT TIME ZONE 'Asia/Bangkok')::date,by_member uuid REFERENCES public.member,amount_outstanding numeric(12,2) NOT NULL,note text,created_at timestamptz NOT NULL DEFAULT now(),sequence bigint GENERATED ALWAYS AS IDENTITY);
GRANT SELECT ON public.collection_event TO authenticated; GRANT ALL ON public.collection_event TO service_role; ALTER TABLE public.collection_event ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_read ON public.collection_event FOR SELECT TO authenticated USING(public.ac_has_role(ARRAY['ac','legal','admin','billing_reader'])); CREATE INDEX ON public.collection_event(customer_id,occurred_at DESC);
CREATE VIEW public.ac_collection_current WITH(security_invoker=true) AS SELECT c.id customer_id,c.name,COALESCE(CASE e.event_type WHEN 'OVERDUE_FLAGGED' THEN 'OVERDUE' WHEN 'SUSPENDED' THEN 'SUSPENDED' WHEN 'LEGAL_FILED' THEN 'LEGAL' WHEN 'WRITTEN_OFF' THEN 'WRITTEN_OFF' ELSE 'NORMAL' END,'NORMAL')::public.collection_status collection_status,COALESCE((SELECT sum(greatest(i.amount-i.paid_amount,0)) FROM public.invoice i WHERE i.customer_id=c.id AND i.status NOT IN ('PAID','VOID','WRITTEN_OFF')),0) outstanding FROM public.customer c LEFT JOIN LATERAL(SELECT event_type FROM public.collection_event WHERE customer_id=c.id ORDER BY sequence DESC LIMIT 1)e ON true;
GRANT SELECT ON public.ac_collection_current TO authenticated,service_role;
CREATE FUNCTION public.ac_invoice_grade(period date,settled date,t date) RETURNS public.payment_grade LANGUAGE sql IMMUTABLE AS $$SELECT CASE WHEN coalesce(settled,t)<=period+14 THEN 'A' WHEN coalesce(settled,t)<(period+interval '1 month')::date THEN 'B' WHEN coalesce(settled,t)<(period+interval '2 months')::date+14 THEN 'C' ELSE 'D' END::public.payment_grade$$;
CREATE FUNCTION public.ac_recompute(t date DEFAULT (now() AT TIME ZONE 'Asia/Bangkok')::date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE c record; prev collection_status; target collection_event_type; debt numeric; BEGIN
DELETE FROM payment_grade_record g WHERE NOT EXISTS(SELECT 1 FROM invoice i WHERE i.customer_id=g.customer_id AND coalesce(i.billing_period,date_trunc('month',i.issue_date)::date)=g.billing_period AND i.invoice_type IN ('RECURRING','SETUP') AND i.status NOT IN ('VOID','WRITTEN_OFF'));
INSERT INTO payment_grade_record(customer_id,billing_period,grade,basis) SELECT customer_id,coalesce(billing_period,date_trunc('month',issue_date)::date),max(ac_invoice_grade(coalesce(billing_period,date_trunc('month',issue_date)::date),settled_date,t)::text)::payment_grade,jsonb_agg(jsonb_build_object('invoice_id',id,'settled_date',settled_date)) FROM invoice WHERE invoice_type IN ('RECURRING','SETUP') AND status NOT IN ('VOID','WRITTEN_OFF') GROUP BY customer_id,coalesce(billing_period,date_trunc('month',issue_date)::date) ON CONFLICT(customer_id,billing_period) DO UPDATE SET grade=excluded.grade,basis=excluded.basis,computed_at=now();
FOR c IN SELECT * FROM customer LOOP
PERFORM 1 FROM customer WHERE id=c.id FOR UPDATE;
SELECT collection_status,outstanding INTO prev,debt FROM ac_collection_current WHERE customer_id=c.id;
target:=NULL;
IF debt=0 AND prev NOT IN ('NORMAL','WRITTEN_OFF') THEN target:='REACTIVATED';
ELSIF debt>0 AND prev NOT IN ('LEGAL','WRITTEN_OFF') THEN
IF EXISTS(SELECT 1 FROM invoice WHERE customer_id=c.id AND invoice_type IN ('RECURRING','SETUP') AND status NOT IN ('PAID','VOID','WRITTEN_OFF') AND ac_invoice_grade(coalesce(billing_period,date_trunc('month',issue_date)::date),NULL,t)='D') THEN
UPDATE service_subscription SET status='SUSPENDED' WHERE customer_id=c.id AND status='ACTIVE'; IF prev<>'SUSPENDED' THEN target:='SUSPENDED'; END IF;
ELSIF prev<>'SUSPENDED' AND EXISTS(SELECT 1 FROM invoice WHERE customer_id=c.id AND status IN ('ISSUED','OVERDUE','PARTIALLY_PAID') AND due_date<t) THEN IF prev<>'OVERDUE' THEN target:='OVERDUE_FLAGGED'; END IF; END IF; END IF;
UPDATE invoice SET status='OVERDUE' WHERE customer_id=c.id AND status IN ('ISSUED','PARTIALLY_PAID') AND due_date<t;
IF target IS NOT NULL THEN
IF target='REACTIVATED' THEN UPDATE service_subscription SET status='ACTIVE' WHERE customer_id=c.id AND status='SUSPENDED'; END IF;
INSERT INTO collection_event(hotel_id,customer_id,event_type,amount_outstanding,occurred_at,note) SELECT hotel_id,c.id,target,debt,t,'Automatic collection evaluation' FROM service_subscription WHERE customer_id=c.id ORDER BY created_at LIMIT 1;
IF NOT FOUND THEN INSERT INTO collection_event(hotel_id,customer_id,event_type,amount_outstanding,occurred_at,note) SELECT hotel_id,c.id,target,debt,t,'Automatic collection evaluation' FROM invoice WHERE customer_id=c.id ORDER BY created_at LIMIT 1; END IF;
END IF; END LOOP; END$$;
CREATE FUNCTION public.ac_daily(t date DEFAULT (now() AT TIME ZONE 'Asia/Bangkok')::date) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE n int; BEGIN
PERFORM pg_advisory_xact_lock(741025);
INSERT INTO invoice(subscription_id,hotel_id,customer_id,service_line,invoice_type,billing_period,customer_segment,issue_date,due_date,amount) SELECT id,hotel_id,customer_id,service_line,'RECURRING',date_trunc('month',t)::date,'EXISTING',t,date_trunc('month',t)::date+due_day-1,monthly_fee FROM service_subscription WHERE status='ACTIVE' AND extract(day FROM t)=billing_day AND date_trunc('month',t)>=date_trunc('month',billing_start_date) ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; PERFORM ac_recompute(t); RETURN n; END$$;
CREATE FUNCTION public.ac_verify(p_payment uuid,p_receipt text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE p payment; i invoice; total numeric; actor uuid; today date:=(now() AT TIME ZONE 'Asia/Bangkok')::date; BEGIN
IF NOT ac_has_role(ARRAY['ac','admin']) THEN RAISE EXCEPTION 'Accounting access required'; END IF;
SELECT id INTO actor FROM member WHERE user_id=auth.uid(); IF actor IS NULL THEN RAISE EXCEPTION 'Accounting member required'; END IF;
SELECT * INTO p FROM payment WHERE id=p_payment; IF NOT FOUND THEN RAISE EXCEPTION 'Payment missing'; END IF;
PERFORM 1 FROM customer WHERE id=(SELECT customer_id FROM invoice WHERE id=p.invoice_id) FOR UPDATE;
SELECT * INTO i FROM invoice WHERE id=p.invoice_id FOR UPDATE;
SELECT * INTO p FROM payment WHERE id=p_payment FOR UPDATE; IF p.verified_by_ac THEN RETURN; END IF;
IF i.status IN ('PAID','VOID','WRITTEN_OFF') THEN RAISE EXCEPTION 'Invoice closed'; END IF;
IF length(trim(p_receipt))=0 THEN RAISE EXCEPTION 'Tax receipt required'; END IF;
UPDATE payment SET verified_by_ac=true,verified_at=today,verified_by=actor WHERE id=p_payment;
SELECT sum(amount) INTO total FROM payment WHERE invoice_id=i.id AND verified_by_ac;
UPDATE invoice SET paid_amount=total,status=CASE WHEN total>=amount THEN 'PAID' ELSE 'PARTIALLY_PAID' END::invoice_status,settled_date=CASE WHEN total>=amount THEN today ELSE NULL END,tax_receipt_no=coalesce(nullif(tax_receipt_no,''),trim(p_receipt)),gateway_paid_date=(SELECT min(gateway_paid_date) FROM payment WHERE invoice_id=i.id) WHERE id=i.id;
PERFORM ac_recompute(today); END$$;
REVOKE ALL ON FUNCTION public.ac_recompute(date),public.ac_daily(date),public.ac_verify(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ac_recompute(date),public.ac_daily(date) TO service_role;
GRANT EXECUTE ON FUNCTION public.ac_verify(uuid,text) TO authenticated,service_role;
CREATE VIEW public.ac_invoice_attributed WITH(security_invoker=true) AS SELECT i.*,s.orm_team_id,s.marcom_member_id,h.name hotel_name,c.name customer_name FROM public.invoice i LEFT JOIN public.service_subscription s ON s.id=i.subscription_id JOIN public.hotel h ON h.id=i.hotel_id JOIN public.customer c ON c.id=i.customer_id;
GRANT SELECT ON public.ac_invoice_attributed TO authenticated,service_role;
CREATE VIEW public.v_ac_debtors WITH(security_invoker=true) AS SELECT DISTINCT customer_id,service_line,billing_period,orm_team_id,marcom_member_id FROM public.ac_invoice_attributed WHERE invoice_type IN ('RECURRING','SETUP') AND status NOT IN ('VOID','WRITTEN_OFF');
CREATE VIEW public.v_ac_invoices_breakdown WITH(security_invoker=true) AS SELECT billing_period,customer_segment,service_line,orm_team_id,marcom_member_id,count(*) invoice_count FROM public.ac_invoice_attributed WHERE status<>'VOID' GROUP BY 1,2,3,4,5;
CREATE VIEW public.v_ac_invoice_ranking WITH(security_invoker=true) AS WITH totals AS(SELECT billing_period,hotel_id,service_line,orm_team_id,marcom_member_id,sum(amount) amount FROM public.ac_invoice_attributed WHERE status NOT IN ('VOID','WRITTEN_OFF') AND billing_period IS NOT NULL GROUP BY 1,2,3,4,5),r AS(SELECT *,dense_rank() OVER(PARTITION BY billing_period,service_line ORDER BY amount DESC) rank FROM totals) SELECT r.*,p.rank previous_month_rank,avg(r.rank) OVER(PARTITION BY r.hotel_id,r.service_line,r.orm_team_id,r.marcom_member_id) lifetime_average_rank FROM r LEFT JOIN r p ON p.hotel_id=r.hotel_id AND p.service_line=r.service_line AND p.billing_period=(r.billing_period-interval '1 month')::date AND p.orm_team_id IS NOT DISTINCT FROM r.orm_team_id AND p.marcom_member_id IS NOT DISTINCT FROM r.marcom_member_id;
CREATE VIEW public.v_ac_grade_distribution WITH(security_invoker=true) AS SELECT g.billing_period,g.grade,i.service_line,i.orm_team_id,i.marcom_member_id,count(DISTINCT g.customer_id) customer_count FROM public.payment_grade_record g JOIN public.ac_invoice_attributed i ON i.customer_id=g.customer_id AND coalesce(i.billing_period,date_trunc('month',i.issue_date)::date)=g.billing_period WHERE i.invoice_type IN ('RECURRING','SETUP') AND i.status NOT IN ('VOID','WRITTEN_OFF') GROUP BY 1,2,3,4,5;
CREATE VIEW public.v_ac_overdue WITH(security_invoker=true) AS SELECT billing_period,service_line,orm_team_id,marcom_member_id,count(DISTINCT customer_id) customer_count,count(*) invoice_count,sum(greatest(amount-paid_amount,0)) outstanding FROM public.ac_invoice_attributed WHERE status IN ('OVERDUE','PARTIALLY_PAID') GROUP BY 1,2,3,4;
CREATE VIEW public.v_ac_suspended WITH(security_invoker=true) AS SELECT i.billing_period,i.service_line,i.orm_team_id,i.marcom_member_id,count(DISTINCT c.customer_id) customer_count FROM public.ac_collection_current c JOIN public.ac_invoice_attributed i USING(customer_id) WHERE c.collection_status='SUSPENDED' GROUP BY 1,2,3,4;
CREATE VIEW public.v_ac_legal WITH(security_invoker=true) AS SELECT i.billing_period,i.service_line,i.orm_team_id,i.marcom_member_id,count(DISTINCT c.customer_id) customer_count FROM public.ac_collection_current c JOIN public.ac_invoice_attributed i USING(customer_id) WHERE c.collection_status='LEGAL' GROUP BY 1,2,3,4;
CREATE VIEW public.v_ac_system_fee WITH(security_invoker=true) AS SELECT hotel_id,hotel_name,customer_id,billing_period,service_line,amount,cadence,status='PAID' paid,orm_team_id,marcom_member_id FROM public.ac_invoice_attributed WHERE invoice_type='SYSTEM_FEE';
GRANT SELECT ON public.v_ac_debtors,public.v_ac_invoices_breakdown,public.v_ac_invoice_ranking,public.v_ac_grade_distribution,public.v_ac_overdue,public.v_ac_suspended,public.v_ac_legal,public.v_ac_system_fee TO authenticated,service_role;